  if ((n - 1) % stride !== 0) {
    out += `<text class="tick" x="${x(n - 1).toFixed(1)}" y="${h - 8}" text-anchor="end">${esc(years[n - 1])}</text>`;
  }
  out += `<line class="axis" x1="${m.l}" x2="${w - m.r}" y1="${m.t + ph}" y2="${m.t + ph}"/>`;
