.chip:hover, .chip.on { color: #fff; border-color: rgba(217, 79, 48, .6); background: rgba(217, 79, 48, .2); }
.tabs { display: inline-flex; gap: 4px; padding: 4px; border: 1px solid var(--line); background: #0f1a2b; border-radius: 10px; margin-bottom: 14px; }
.tab { border: 0; background: transparent; color: var(--muted); border-radius: 7px; padding: 7px 17px; font-size: 12px; font-weight: 700; }
.tab:hover { color: var(--text); }
.tab.on { background: var(--accent); color: #fff; box-shadow: 0 3px 12px rgba(217, 79, 48, .25); }

/* The economy price metric toggle lives inline in the Consumer prices panel header. */
.price-panel .card-head { flex-wrap: wrap; align-items: center; }
.price-panel .card-head h3 { margin: 0; font-size: 18px; line-height: 1.3; }
.price-panel .segmented {
  display: inline-flex; align-items: center; flex: none; gap: 2px; margin: 0;
  padding: 3px; border: 1px solid var(--line); border-radius: 9px; background: var(--track);
}
.price-panel .segmented button {
  border: 0; border-radius: 6px; background: transparent; color: var(--muted);
  padding: 6px 11px; font-size: 11.5px; font-weight: 700; white-space: nowrap;
}
.price-panel .segmented button:hover { color: var(--text); }
.price-panel .segmented button[aria-pressed="true"] {
  background: var(--accent); color: #fff; box-shadow: 0 2px 8px rgba(217, 79, 48, .25);
}

/* Detail blocks */
.stat-list { display: flex; flex-direction: column; }
.stat-row { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 10px 0; border-bottom: 1px solid var(--line); }
.stat-row:last-child { border-bottom: 0; }
.stat-row div { display: flex; flex-direction: column; }
.stat-row strong { font-size: 13px; }
.stat-row span { font-size: 10.5px; color: var(--dim); }
.stat-row b { font-size: 23px; color: var(--accent); font-variant-numeric: tabular-nums; }
.gold { color: var(--gold) !important; }
.teal { color: var(--teal) !important; }
.negative { color: #ff8065 !important; }
.mini-note { color: var(--muted); font-size: 11.5px; margin: 12px 0 0; }
.number-notes { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; }
.number-notes b { display: block; font-size: 26px; letter-spacing: -.03em; color: var(--accent); }
.number-notes p { color: var(--muted); font-size: 12px; margin: 5px 0 0; }
.trade-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; margin-bottom: 12px; }
.trade-head b { display: block; font-size: 30px; letter-spacing: -.03em; line-height: 1.2; }
.trade-head small { color: var(--dim); font-size: 11px; }
.trade-note { color: var(--muted); font-size: 11.5px; max-width: 22ch; text-align: right; }
.micro { display: block; font-size: 9.5px; letter-spacing: .17em; color: var(--muted); font-weight: 700; }

/* Economy KPI strip: keep value, label and source on separate, readable lines. */
.economy-facts { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 12px; margin: 0 0 18px; }
.economy-facts .fact {
  display: flex; flex-direction: column; gap: 5px; min-width: 0; padding: 14px 16px;
  border: 1px solid var(--line); border-radius: 12px;
  background: linear-gradient(180deg, var(--panel2), var(--panel));
}
.economy-facts .fact b { font-size: 27px; letter-spacing: -.03em; line-height: 1.15; }
.economy-facts .fact span { color: var(--muted); font-size: 11.5px; }
.economy-facts .fact small { color: var(--dim); font-size: 10px; margin-top: 2px; }

.stat-grid { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 12px; margin-bottom: 16px; }
.stat-tile { display: flex; flex-direction: column; gap: 2px; padding: 14px 15px; background: var(--panel); border: 1px solid var(--line); border-radius: 12px; }
.stat-tile span { font-size: 10px; letter-spacing: .12em; text-transform: uppercase; color: var(--muted); font-weight: 700; }
.stat-tile b { font-size: 25px; letter-spacing: -.03em; }
.stat-tile small { color: var(--dim); font-size: 9.5px; }
.callout { display: flex; gap: 12px; align-items: flex-start; margin-top: 14px; padding: 12px 14px; border-radius: 10px; border: 1px solid rgba(227, 184, 98, .3); background: rgba(227, 184, 98, .07); }
.callout-mark { flex: none; width: 19px; height: 19px; border-radius: 50%; color: #141b27; background: var(--gold); font-weight: 800; font-size: 12px; text-align: center; line-height: 19px; }
.callout p { margin: 0; color: #ddcfb2; font-size: 12px; }
.callout strong { color: var(--gold); }

/* Prefecture explorer */
.table-toolbar input[type="search"], .table-toolbar select {
  background: #0f1a2b; border: 1px solid var(--line); color: var(--text);
  border-radius: 7px; padding: 8px 10px; font-size: 12px; min-width: 150px;
}
.table-toolbar input[type="search"] { flex: 1 1 190px; max-width: 280px; }
.scroll-hint { display: none; }
.table-scroll { overflow-x: auto; border: 1px solid var(--line); border-radius: 10px; }
.pref-table { width: 100%; min-width: 580px; border-collapse: collapse; font-size: 12.5px; }
.pref-table th, .pref-table td { padding: 9px 12px; text-align: left; border-bottom: 1px solid #25344b; white-space: nowrap; }
.pref-table thead th { background: #16243a; position: sticky; top: 0; z-index: 1; }
.pref-table tbody tr:last-child th, .pref-table tbody tr:last-child td { border-bottom: 0; }
.pref-table tbody tr { cursor: pointer; transition: background .12s ease; }
.pref-table tbody tr:hover { background: #1c2b41; }
.pref-table tbody tr.selected { background: rgba(217, 79, 48, .14); box-shadow: inset 3px 0 0 var(--accent); }
.pref-table .num { text-align: right; font-variant-numeric: tabular-nums; color: #d8e2f0; }
.sort-btn { border: 0; background: transparent; color: var(--muted); padding: 3px 0; font-size: 10px; letter-spacing: .08em; text-transform: uppercase; font-weight: 750; }
.sort-btn:hover, .sort-btn.on { color: var(--accent); }
.pref-table .empty { color: var(--muted); text-align: center !important; padding: 26px 12px !important; }
.detail-card { margin-top: 14px; padding: 17px 18px; border: 1px solid var(--line); border-radius: 11px; background: #101b2b; }
.detail-head { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
.detail-head h3 { margin: 2px 0 0; font-size: 22px; letter-spacing: -.02em; }
.region-tag { border: 1px solid rgba(86, 177, 164, .45); background: rgba(86, 177, 164, .12); color: #8ee0d3; border-radius: 999px; padding: 4px 11px; font-size: 10.5px; font-weight: 700; }
.detail-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin-top: 14px; }
.detail-grid > div { border-left: 2px solid #30425d; padding-left: 10px; }
.detail-grid span { display: block; color: var(--muted); font-size: 10px; text-transform: uppercase; letter-spacing: .1em; }
.detail-grid b { font-size: 17px; font-variant-numeric: tabular-nums; }
.detail-bar { height: 6px; margin-top: 15px; border-radius: 3px; background: var(--track); overflow: hidden; }
.detail-bar > div { height: 100%; border-radius: 3px; background: linear-gradient(90deg, var(--accent), var(--gold)); }
.detail-note { margin: 9px 0 0; font-size: 11.5px; color: var(--muted); }

/* Footer */
.site-footer { border-top: 1px solid var(--line); padding: 20px 0 32px; color: var(--dim); font-size: 11px; }
.footer-inner { display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
.footer-inner strong { color: var(--muted); letter-spacing: .12em; }

@media (max-width: 1060px) {
  .kpi-grid, .stat-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .header-stamp { display: none; }
}

@media (max-width: 760px) {
  .wrap { padding: 0 16px; }
  .page { padding: 22px 0 44px; }
  .header-inner { flex-wrap: wrap; gap: 10px; min-height: 0; padding: 11px 0 9px; }
  .nav { width: 100%; margin-left: 0; flex-wrap: nowrap; overflow-x: auto; padding-bottom: 2px; }
  .nav a { white-space: nowrap; font-size: 12px; padding: 7px 10px; }
  .hero { grid-template-columns: 1fr; padding: 26px 22px; gap: 6px; margin-top: 12px; }
  .hero h1 { font-size: clamp(38px, 9vw, 52px); }
  .hero-visual .map-motif { max-width: 260px; opacity: .9; }
  .grid-2 { grid-template-columns: 1fr; }
  .number-notes { grid-template-columns: 1fr; gap: 13px; }
  .stat-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .detail-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .card { padding: 17px; }
  .toolbar { gap: 9px; }
  .preset-group { margin-left: 0; }
  .trade-note { display: none; }
  .scroll-hint { display: block; color: var(--dim); font-size: 11px; margin: 0 0 8px; }
}

@media (max-width: 480px) {
  .kpi-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
  .kpi { min-height: 140px; padding: 13px; }
  .kpi:nth-child(5) { grid-column: span 2; min-height: 120px; }
  .kpi-value { font-size: 26px; }
  .spark { width: 82px; }
  .stat-tile:nth-child(5) { grid-column: span 2; }
  .hero { padding: 22px 18px; }
  .hero h1 { font-size: 38px; }
  .hero-actions { gap: 14px; margin-top: 20px; }
  .card h2 { font-size: 17px; }
  .toolbar input[type="range"] { width: 100%; flex: 1 1 100px; }
  .table-toolbar input[type="search"] { max-width: none; width: 100%; }
  .table-toolbar select { flex: 1 1 130px; }
  .detail-head h3 { font-size: 20px; }
  .footer-inner { display: block; }
  .footer-inner span { display: block; margin-top: 3px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; scroll-behavior: auto !important; }
}
